using System;using System.Data;using System.Data.SqlClient;
namespace Training.Manager{public partial class SessionReportDetails:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string MID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(MID)||Session["TrainingID"]==null||Session["SessionID"]==null){Response.Redirect("~/Manager/SessionReport.aspx");return;}if(!IsPostBack)LoadSession();}
private bool Access(){object v=obj.ExecuteScalar("SELECT COUNT(*) FROM ManagerMaster M INNER JOIN TrainingLocationMaster L ON M.TrainingLocationID=L.TrainingLocationID INNER JOIN TrainingDetails TD ON TD.TrainingLocation=L.TrainingLocation INNER JOIN SessionMaster SM ON SM.TrainingID=TD.TrainingID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y' AND TD.TrainingID=@TrainingID AND SM.SessionID=@SessionID",new SqlParameter[]{new SqlParameter("@ManagerID",MID),new SqlParameter("@TrainingID",Session["TrainingID"].ToString()),new SqlParameter("@SessionID",Session["SessionID"].ToString())});return v!=null&&Convert.ToInt32(v)>0;}
private void LoadSession(){if(!Access()){Response.Redirect("~/Manager/SessionReport.aspx");return;}DataTable d=obj.GetDataTable("SELECT TOP 1 SM.TrainingID,TD.Batch,SM.SessionNo,SM.SessionName,SM.SessionDate FROM SessionMaster SM INNER JOIN TrainingDetails TD ON SM.TrainingID=TD.TrainingID WHERE SM.SessionID=@SessionID AND SM.TrainingID=@TrainingID",new SqlParameter[]{new SqlParameter("@SessionID",Session["SessionID"].ToString()),new SqlParameter("@TrainingID",Session["TrainingID"].ToString())});if(d.Rows.Count==0){Response.Redirect("~/Manager/SessionReport.aspx");return;}lblTrainingID.Text=d.Rows[0]["TrainingID"].ToString();lblBatch.Text=d.Rows[0]["Batch"].ToString();lblSession.Text=d.Rows[0]["SessionNo"].ToString()+" - "+d.Rows[0]["SessionName"].ToString();lblDate.Text=d.Rows[0]["SessionDate"].ToString();}
protected void btnAttendance_Click(object s,EventArgs e){Response.Redirect("~/Manager/AttendanceReport.aspx");}protected void btnExam_Click(object s,EventArgs e){Response.Redirect("~/Manager/ExamResultReport.aspx");}protected void btnFeedback_Click(object s,EventArgs e){Response.Redirect("~/Manager/FeedbackReport.aspx");}protected void btnBack_Click(object s,EventArgs e){Response.Redirect("~/Manager/SessionReport.aspx");}}}